with ins as (
  insert into clinic_exams (employee_id, exam_date, exam_type, history, vitals, systems, tests, problems, fitness, restrictions, recommendations, next_exam_date, created_by)
  select e.id, date '2026-05-17', 'periodic', s.history, s.vitals, '{}'::jsonb, s.tests, s.problems, s.fitness, s.restrictions, s.recommendations,
         date '2026-05-17' + 365, 'mohammad.allhrezaei@gmail.com'
  from _ex_import s
  join employees e on btrim(e.emp_id::text) = s.code
  where not exists (select 1 from clinic_exams x where x.employee_id = e.id and x.exam_date = date '2026-05-17' and x.exam_type = 'periodic')
  returning employee_id
)
select 'ثبت شد' as "وضعیت", (select count(*) from ins)::text as "کد_یا_تعداد", null::text as "نام"
union all
select 'کد پرسنلی در جدول پرسنل پیدا نشد', s.code, s.name
from _ex_import s left join employees e on btrim(e.emp_id::text) = s.code where e.id is null
union all
select 'از قبل ثبت شده بود (رد شد)', s.code, s.name
from _ex_import s join employees e on btrim(e.emp_id::text) = s.code
where exists (select 1 from clinic_exams x where x.employee_id = e.id and x.exam_date = date '2026-05-17' and x.exam_type = 'periodic');

commit;
